import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Texture plane ---
  const geometry = new PlaneGeometry(1.5, 0.9375); // 1.5 wide, 0.9375 high (1.6:1)
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: true,
  });
  const plane = new Mesh(geometry, material);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // Load texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // --- Text ---
  const textContent = config.textContent?.[0] || { text: 'Collection 3', role: 'headline', typography: { fontSize: 0.34 } };
  const fontSize = textContent.typography?.fontSize || 0.34;
  const text = ctx.fontAtlas.createText(textContent.text, {
    fontSize,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 0.34 * 10, // approximate max width in scene units
  });
  text.position.set(0, 0, 0.001);
  group.add(text);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
